import {commonRequirements} from './common-career-data.js?v=0.31.0';
import {professionalRequirements} from './professional-data.js?v=0.31.0';
// Texas career-entry snapshot. Education expectations are separate from legal authority.
// Ordinary-role findings are an editorial review of the state permit inventory,
// not a claim that every possible activity within an occupation is unregulated.
import {extraCareerSpecs} from './catalog-extra.js?v=0.31.0';

const reviewed='2026-10-16';
const inventory='https://gov.texas.gov/business/page/business-permits-office';
const ooh=p=>`https://www.bls.gov/ooh/${p}.htm`;
const originals={
 'industrial-design':{entry:'Bachelor’s degree and a strong portfolio are typical.',training:'Build a portfolio through studio projects and internships.',sourceURL:ooh('arts-and-design/industrial-designers')},
 software:{entry:'Bachelor’s degree in computing or a related field is typical.',training:'Build software projects, algorithms, and team experience.',sourceURL:ooh('computer-and-information-technology/software-developers')},
 'social-research':{entry:'Bachelor’s degree is typical.',training:'Develop research methods, statistics, and supervised research experience.',sourceURL:'https://www.bls.gov/emp/tables/occupational-projections-and-characteristics.htm'},
 'environmental-science':{entry:'Bachelor’s degree in a natural science is typical.',training:'Develop laboratory, field, and quantitative skills.',sourceURL:ooh('life-physical-and-social-science/environmental-scientists-and-specialists')},
 'market-research':{entry:'Bachelor’s degree is typical.',training:'Develop statistics, interviewing, and research communication.',sourceURL:ooh('business-and-financial/market-research-analysts')},
 writing:{entry:'A bachelor’s degree is typical for many salaried roles.',training:'Build writing samples, editing practice, and subject knowledge.',sourceURL:ooh('media-and-communication/writers-and-authors')},
 'mechanical-engineering':{entry:'Bachelor’s degree in engineering is typical.',training:'Build mathematics, laboratory, and design skills.',sourceURL:ooh('architecture-and-engineering/mechanical-engineers')},
 teaching:{entry:'Bachelor’s degree plus educator preparation for standard certification.',training:'Complete approved preparation and the required classroom experience.',sourceURL:'https://tea.texas.gov/educators/certification/initial-certification/becoming-classroom-teacher-texas'},
 tattoo:{entry:'Portfolio and supervised studio training. No college degree is legally required for tattooing.',training:'Learn aseptic technique, infection prevention, equipment safety, and supervised tattoo practice.',sourceURL:'https://www.dshs.texas.gov/tattoo-body-piercing-studios/laws-rules-tattoo-body-piercing-studios'}
};

const concise={
 nursing:['Approved nursing degree or diploma.','Pass NCLEX-RN and the Texas nursing law exam.'],
 'physician-assistant':['Graduate from an accredited PA program.','Pass PANCE and the Texas law exam.'],
 'physical-therapy':['DPT is the current entry degree.','Complete clinical training and pass NPTE.'],
 'occupational-therapy':['Accredited entry-level OT master’s or doctorate.','Complete fieldwork and pass NBCOT.'],
 pharmacy:['PharmD is the current U.S. entry route.','Complete internship hours; pass NAPLEX and MPJE.'],
 'dental-hygiene':['Accredited dental hygiene program.','Pass national, clinical, and Texas law assessments.'],
 'speech-language':['Graduate speech-language pathology degree.','Supervised internship and national exam.'],
 sonography:['Associate degree or an eligible certificate route.','Clinical placements and employer-recognized credentials.'],
 'respiratory-therapy':['Approved respiratory care program.','NBRC credential and Texas law exam.'],
 nutrition:['RDN route: graduate degree and accredited preparation.','Supervised practice and the CDR exam.'],
 'social-work':['Accredited BSW for the LBSW route.','ASWB bachelor’s exam and Texas law exam.'],
 'school-psychology':['Graduate school psychology preparation.','1,200-hour internship and required exams.'],
 'data-science':['Bachelor’s degree is typical.','Statistics, coding, and applied projects.'],
 statistics:['Master’s degree is typical.','Study design and statistical computing.'],
 'information-security':['Bachelor’s degree and related experience are typical.','Develop systems, networking, and security practice.'],
 'systems-analysis':['Bachelor’s degree is typical.','Systems projects and business communication.'],
 accounting:['Bachelor’s degree is typical.','CPA is a separate licensed credential.'],
 'financial-analysis':['Bachelor’s degree is typical.','Financial modeling, research, and accounting.'],
 'human-resources':['Bachelor’s degree is typical.','Internships and employment-practice knowledge.'],
 logistics:['Bachelor’s degree is typical.','Operations, supply chains, and data skills.'],
 'project-management':['Bachelor’s degree is typical.','Develop industry and project experience.'],
 economics:['Master’s degree is typical for economist roles.','Econometrics, research, and mathematics.'],
 law:['Undergraduate study, then an approved law degree.','Bar exam, MPRE, and Texas Law Course.'],
 paralegal:['Associate degree or paralegal certificate is typical.','Legal research and supervised legal work.'],
 'urban-planning':['Master’s degree is typical.','GIS, planning law, and internships.'],
 'civil-engineering':['Engineering bachelor’s degree is typical.','Design practice; PE route for regulated services.'],
 'electrical-engineering':['Engineering bachelor’s degree is typical.','Circuits, laboratory work, and design.'],
 'biomedical-engineering':['Engineering bachelor’s degree is typical.','Biology, device design, and laboratory work.'],
 chemistry:['Bachelor’s degree is typical.','Research roles may need graduate study.'],
 'biological-technician':['Bachelor’s degree is typical.','Laboratory techniques and supervised research.'],
 conservation:['Bachelor’s degree is typical.','Ecology, fieldwork, and resource management.'],
 'food-science':['Bachelor’s degree is typical.','Food safety, chemistry, and laboratory practice.'],
 veterinary:['DVM or an accepted equivalent route.','NAVLE and the Texas State Board Exam.'],
 architecture:['Professional architecture degree.','AXP experience and the ARE exams.'],
 'construction-management':['Bachelor’s degree is typical; experience routes exist.','Learn construction methods and project management.'],
 'graphic-design':['Bachelor’s degree is typical.','Build a visual design portfolio.'],
 animation:['Bachelor’s degree is typical.','Build an animation portfolio and production skills.'],
 'film-editing':['Bachelor’s degree is typical.','Build an editing reel and production experience.'],
 'public-relations':['Bachelor’s degree is typical.','Writing, audience research, and internships.'],
 librarian:['Library/information science master’s is typical.','School library certification is a separate route.'],
 interpreting:['Bachelor’s degree is typical.','Advanced language fluency and interpreting practice.'],
 'exercise-physiology':['Bachelor’s degree is typical.','Clinical exercise experience and relevant certification.'],
 epidemiology:['Master’s degree is typical.','Public health, statistics, and study design.'],
 geoscience:['Geoscience bachelor’s degree is typical.','Field practice; PG route for regulated services.'],
 'industrial-engineering':['Engineering bachelor’s degree is typical.','Statistics, process design, and systems analysis.'],
 electrician:['Paid apprenticeship is a common route.','Apprentice license, supervised hours, and exam.'],
 plumbing:['Registered apprenticeship is a common route.','Supervised hours, required instruction, and exam.'],
 hvac:['Technical training plus supervised work.','Technician registration; EPA credential for refrigerants.'],
 carpentry:['High school preparation and on-the-job learning.','Apprenticeship, construction skills, and safety.'],
 automotive:['Technical certificate or employer training.','Hands-on diagnostics; ASE credentials are voluntary.'],
 emt:['High school diploma/GED and approved EMT course.','National Registry exam and Texas certification.'],
 chef:['Kitchen experience is the usual foundation.','Culinary school is optional; food safety training applies.'],
 'dental-assisting':['Employer training or a dental assisting program.','Texas radiology certificate for dental X-rays.']
};
const specs={...originals,...Object.fromEntries(extraCareerSpecs.map(s=>[s.id,s]))};
export const texasRequirements=Object.fromEntries(Object.entries(specs).map(([id,s])=>{
 const [entry,training]=concise[id]||[s.entry,s.training];
 return [id,{jurisdiction:'Texas',checkedAt:reviewed,status:'reviewed',confidence:'moderate',licenseKind:'no_general_license',summary:'No general Texas occupational license.',bullets:[entry,training],typicalEntry:entry,training,legalMinimum:'No general Texas occupational license for the ordinary duties of this role.',license:'No general occupational license.',detail:'Degree and portfolio expectations come from the occupation’s typical preparation, not a Texas licensing mandate. This finding covers ordinary employee duties. A separately regulated service, protected title, business operation, or licensed clinical duty has its own rules.',sourceURLs:[inventory,s.sourceURL]}];
}));
const set=(id,summary,bullets,detail,sourceURLs,licenseKind='required')=>Object.assign(texasRequirements[id],{summary,bullets,detail,sourceURLs,licenseKind,confidence:'high',legalMinimum:summary,license:summary,status:'sourced'});

const peURL='https://pels.texas.gov/lic_basic.htm';
for(const id of ['mechanical-engineering','civil-engineering','electrical-engineering','biomedical-engineering','industrial-engineering'])set(id,'PE license for regulated engineering services.',[concise[id]?.[0]||originals[id].entry,'PE route: approved degree, exams, and qualifying experience.','A PE is not required for every entry engineering job.'],'Texas regulates engineering practice and the PE title. The standard accredited-degree route requires at least four years of qualifying experience, FE and PE examinations (unless a waiver applies), and the Texas ethics examination. Statutory exemptions cover some employee work, including qualifying industrial work; exemptions do not authorize offering engineering services to the public outside their scope. A degree alone does not confer a PE license.',[peURL,'https://pels.texas.gov/lic_faq.htm','https://statutes.capitol.texas.gov/Docs/OC/htm/OC.1001.htm'],'scope_dependent');

set('teaching','Texas educator certificate: standard public-school route.',['Bachelor’s degree and approved teacher preparation.','Pass the exams for the teaching assignment.','Apply for certification and complete fingerprinting.'],'This is the standard certification route for the catalog’s middle-school teacher role. Private schools and legally permitted district exceptions are different employment routes. Texas is phasing in additional certification rules; some approved districts have implementation delays. The standard route remains the clearest preparation target. Certain career/technical certificates have degree exceptions that do not establish a general exception for middle-school subject teachers.',['https://tea.texas.gov/educators/certification/initial-certification/becoming-classroom-teacher-texas','https://tea.texas.gov/texas-educators/certification'],'scope_dependent');
set('tattoo','Work in a Texas DSHS-licensed tattoo studio.',['No separate DSHS individual tattoo-artist license.','Training in aseptic technique and infection prevention.','College is optional; supervised studio practice matters.'],'Texas licenses tattoo studios and temporary locations rather than issuing a separate individual artist license. Artists must have education, training, experience, or a combination sufficient for aseptic technique and preventing bloodborne pathogen transmission. Studio hygiene, sterilization, records, and client-age/consent rules apply. A college art degree does not replace this training or the studio license. The state rules do not establish a universal apprenticeship duration or require a particular branded training certificate.',['https://www.dshs.texas.gov/tattoo-body-piercing-studios','https://www.dshs.texas.gov/tattoo-body-piercing-studios/laws-rules-tattoo-body-piercing-studios','https://www.dshs.state.tx.us/sites/default/files/tattoo-piercing/PDF/TattooBodyPiercingRules.pdf'],'establishment_license');
set('nursing','Texas RN license or valid compact privilege.',['Graduate from an approved nursing program.','Pass NCLEX-RN and the Texas nursing law exam.','Complete the Board application and fingerprinting.'],'For a first Texas RN license, approved nursing education, the NCLEX-RN, Nursing Jurisprudence Examination, and Board eligibility review apply. Associate, bachelor’s, and approved diploma routes can lead to RN licensure. A BSN can support broader education and employer opportunities; it is not the sole legal entry route. A qualifying multistate compact license can also authorize practice in Texas.',['https://bon.texas.gov/licensure_examination.asp.html','https://www.bon.texas.gov/faq_licensure.asp.html']);
set('physician-assistant','Texas physician assistant license.',['Accredited PA program; current entry programs are graduate level.','PANCE, NCCPA certification, and Texas law exam.','Practice with physician supervision.'],'The Texas Physician Assistant Board requires approved PA education, PANCE passage, current NCCPA certification for initial licensure, the Texas jurisprudence exam, and eligibility review. Texas PAs practice under supervising physicians. Prescribing additionally needs an appropriate prescriptive delegation agreement.',['https://www.tmb.texas.gov/index.php/apply-renew/physician-assistant/physician-assistant-license-application','https://www.tmb.texas.gov/file/physician-assistant-eligibility-checklist']);
set('physical-therapy','Texas physical therapist license.',['Accredited professional PT education; DPT is current entry.','Pass NPTE and the Texas law assessment.','Apply with transcripts and fingerprinting.'],'The Texas Board of Physical Therapy Examiners requires qualifying professional education, the national licensing examination, jurisprudence requirements, and eligibility review. Undergraduate kinesiology alone does not qualify someone to practice physical therapy. This record is for physical therapists, not physical therapist assistants.',['https://ptot.texas.gov/apply-for-a-license/','https://statutes.capitol.texas.gov/Docs/OC/htm/OC.453.htm']);
set('occupational-therapy','Texas occupational therapist license.',['Accredited entry-level OT master’s or doctorate.','Complete fieldwork and pass NBCOT.','Pass Texas law exam and complete fingerprinting.'],'Texas requires qualifying entry-level occupational therapy education, NBCOT examination passage, the jurisprudence exam, and Board eligibility review. The graduate entry route is for occupational therapists; occupational therapy assistants have a different education and license.',['https://ptot.texas.gov/ot-application/','https://www.ptot.texas.gov/wp-content/uploads/Initial-Licensing-General-Information.pdf','https://www.nbcot.org/get-certified/eligibility']);
set('pharmacy','Texas pharmacist license.',['PharmD is the current U.S. entry degree.','Complete 1,740 qualifying internship hours.','Pass NAPLEX and MPJE; submit Board application.'],'Texas State Board of Pharmacy’s examination route requires an accepted pharmacy degree or approved foreign graduate equivalency, age 18, the required 1,740 internship hours, national and pharmacy-law examinations, and the Board’s application requirements. The statute also recognizes qualifying legacy pharmacy bachelor’s degrees; a general science bachelor’s is not a pharmacy qualification.',['https://www.pharmacy.texas.gov/applicants/pharmacist-exam.asp']);
set('dental-hygiene','Texas dental hygienist license.',['Complete accredited dental hygiene education.','Pass national and accepted clinical examinations.','Complete Texas law and required application training.'],'The Texas State Board of Dental Examiners licenses dental hygienists. The exam route includes qualifying dental hygiene education, national and accepted clinical exam results, jurisprudence, CPR/BLS and required application items including human trafficking prevention training and fingerprinting. This is distinct from a dental assistant radiology certificate.',['https://tsbde.texas.gov/licensing/hygienists/hygienist-license-by-exam/','https://statutes.capitol.texas.gov/Docs/OC/htm/OC.256.htm']);
set('speech-language','Texas speech-language pathologist license.',['Graduate degree and qualifying clinical preparation.','Complete a licensed, supervised internship.','Pass national and Texas law examinations.'],'TDLR’s speech-language pathology route includes a qualifying graduate degree, clinical experience, an internship, examinations, and application eligibility requirements. An intern license authorizes the supervised internship stage, normally at least 36 weeks and 1,260 supervised hours. The ASHA Certificate of Clinical Competence can document some education, experience, and examination requirements; it does not by itself replace the Texas license.',['https://www.tdlr.texas.gov/slpa/slp-license-apply.htm','https://www.tdlr.texas.gov/slpa/slp-intern-apply.htm']);
set('sonography','No Texas sonographer occupational license.',['Associate degree or an eligible certificate route.','Complete supervised clinical sonography training.','Employers commonly seek a recognized sonography credential.'],'This covers diagnostic ultrasound, not X-ray or other ionizing-radiation work. Texas medical radiologic technologist regulation defines radiation as ionizing radiation, so its certification does not establish a sonography license. ARDMS and related credentials are professional certifications with their own education/clinical prerequisites. An employer can require them even though Texas has no general sonographer license.',['https://statutes.capitol.texas.gov/Docs/OC/pdf/OC.601.pdf','https://www.bls.gov/ooh/healthcare/diagnostic-medical-sonographers.htm','https://www.ardms.org/get-certified/'],'no_general_license');
set('respiratory-therapy','Texas respiratory care practitioner certificate.',['Complete an approved respiratory care program.','Hold a qualifying NBRC credential.','Pass Texas law exam and complete fingerprinting.'],'The Texas Board of Medical Radiologic Technology issues the RCP certificate through the Texas Medical Board. The full-certificate route requires an approved program transcript, NBRC credential verification, jurisprudence and eligibility review. A temporary certificate is a different, limited application route.',['https://www.tmb.texas.gov/index.php/apply-renew/respiratory-care-practitioner/respiratory-care-practitioner-certificate-application','https://www.tmb.texas.gov/node/3337']);
set('nutrition','Texas protects “Licensed Dietitian” and “LD.”',['Generic “nutritionist” is not a licensed Texas title.','RDN route: graduate degree, supervised practice, and exam.','A Texas LD license is a separate protected credential.'],'Texas dietetics is a title act, not a blanket nutrition-practice license. A license is required to use Licensed Dietitian or LD; Dietitian and Nutritionist alone do not require that license. Registered Dietitian/RD requires CDR registration. New RDN exam eligibility requires a graduate degree and approved preparation. Texas LD applicants may document current CDR registration or satisfy TDLR’s separate education, experience, and examination route, including at least 900 supervised hours. Do not infer that every nutrition worker legally needs a graduate degree.',['https://www.tdlr.texas.gov/media/pdf/DTN-at-a-glance.pdf','https://www.tdlr.texas.gov/diet/dietapply.htm','https://www.cdrnet.org/graduatedegree'],'protected_title');
set('social-work','Texas social work license.',['LBSW: accredited BSW, ASWB exam, and Texas law exam.','LMSW: accredited social work master’s and exam.','Independent clinical practice requires the LCSW route.'],'Texas licenses social work at baccalaureate, master’s, and clinical levels. A sociology degree is useful study but does not substitute for the accredited social work degree required by the standard LBSW or LMSW route. LCSW adds qualifying supervised clinical experience and the clinical examination. The earnings category here is child, family, and school social workers, not an exclusive LCSW salary series. Statutory exemptions and employer duties can affect particular positions.',['https://bhec.texas.gov/texas-state-board-of-social-worker-examiners/applying-for-a-social-work-license/how-to-become-an-lbsw/','https://bhec.texas.gov/texas-state-board-of-social-worker-examiners/applying-for-a-social-work-license/']);
set('school-psychology','Texas school psychologist license.',['Qualifying graduate school psychology preparation.','1,200-hour internship; at least 600 in public school.','Pass school psychology and Texas law examinations.'],'The Texas Behavioral Health Executive Council’s school psychologist route is governed by Rule 463.9. Approved/accredited school psychology preparation or specified graduate psychology coursework, an internship, examinations, fingerprinting, and application eligibility apply. Existing materials may use the former LSSP label. This school-practice credential does not grant the full independent scope of a licensed psychologist. A psychology bachelor’s alone is insufficient.',['https://bhec.texas.gov/texas-state-board-of-examiners-of-psychologists/applying-for-a-psychology-license/how-to-become-a-licensed-school-psychologist/','https://bhec.texas.gov/texas-state-board-of-examiners-of-psychologists/applying-for-a-psychology-license/']);

set('accounting','CPA is licensed; ordinary accounting roles differ.',['Bachelor’s degree is typical for accounting employment.','CPA: qualifying coursework, CPA exam, and supervised experience.','2026 routes: 150 credits + 1 year, or 120 + 2 years.'],'Texas State Board of Public Accountancy protects the CPA credential and regulates public accountancy. The alternative 120-credit/two-year route took effect August 1, 2026 alongside the 150-credit/one-year route; both have specific accounting/business course, examination, ethics, and eligibility requirements. The credit count alone does not qualify someone. Ordinary employee bookkeeping/accounting duties are not a blanket requirement to hold a CPA.',['https://www.tsbpa.texas.gov/exam-qualification/certification-forms.html','https://www.tsbpa.texas.gov/pdffiles/x0036.pdf'],'scope_dependent');
set('financial-analysis','Research roles differ from regulated investment advice.',['Bachelor’s degree is typical.','General financial analysis has no blanket Texas license.','Securities sales/advice can require firm and individual registration.'],'Texas State Securities Board regulates dealers, agents, investment advisers, and representatives. Corporate financial analysis or research does not automatically make someone an investment adviser. Providing investment advice for compensation or selling securities can trigger registration, qualification examinations, and firm supervision under the applicable rules. CFA is a professional credential, not a substitute for legally required registration.',['https://ssb.texas.gov/securities-professionals','https://www.ssb.texas.gov/securities-professionals/dealer-adviser-registration/getting-started-registered-investment-adviser-3',inventory],'scope_dependent');
set('law','Texas bar admission to practice law.',['Approved law-degree route after undergraduate study.','Bar exam, MPRE, and Texas Law Course.','Character and fitness review and admission formalities.'],'The standard first-license route uses an approved law degree and the Texas Board of Law Examiners’ examination/admission process. MPRE score, Texas Law Course, character and fitness, and other admission conditions apply. Rules also provide alternative eligibility for certain experienced or foreign-trained lawyers; these are not a high-school-to-law shortcut. A political science major alone confers no authority to practice law.',['https://ble.texas.gov/current','https://www.ble.texas.gov/faq','https://ble.texas.gov/browseprintform.action?formId=5']);
set('paralegal','No Texas paralegal license; attorney supervision matters.',['Associate degree or paralegal certificate is typical.','Legal research and document skills.','Paralegals cannot independently practice law.'],'Texas does not require a general paralegal occupational license. Employer education requirements and voluntary specialist credentials are separate. Paralegal work must stay within lawful delegation and supervision; this occupation does not authorize independent legal advice or legal representation.',['https://txpd.org/faq/what-are-the-requirements-to-become-a-paralegal-in-the-state-of-texas/','https://www.bls.gov/ooh/legal/paralegals-and-legal-assistants.htm',inventory],'no_general_license');
set('urban-planning','No general Texas urban planner license.',['Master’s degree is typical.','Develop GIS, planning law, and public-engagement skills.','AICP is voluntary; licensed design work is separate.'],'Urban planning employment does not generally require a Texas occupational license. AICP is a professional certification, not a Texas planning license. A planner’s role does not itself authorize regulated architecture, surveying, engineering, or geoscience services.',['https://gov.texas.gov/business/page/business-permits-office','https://www.bls.gov/ooh/life-physical-and-social-science/urban-and-regional-planners.htm','https://www.planning.org/certification/'],'no_general_license');
set('environmental-science','No blanket license for environmental scientist roles.',['Bachelor’s degree in a natural science is typical.','Develop field, laboratory, and quantitative skills.','Geoscience, engineering, and cleanup scopes have separate licenses.'],'Ordinary environmental scientist employment has no blanket Texas occupational license. Public geoscience and engineering services can require PG/PE authority. TCEQ separately licenses leaking petroleum storage tank corrective-action specialists/project managers and other regulated environmental activities. This role title does not authorize those services automatically.',['https://www.tceq.texas.gov/licensing/licenses/lpstlic','https://tbpg.state.tx.us/p-g-licensing-faqs/',inventory],'scope_dependent');
set('veterinary','Texas veterinarian license.',['DVM or accepted foreign-education equivalency.','Pass NAVLE and Texas State Board Exam.','Complete fingerprinting and eligibility review.'],'Texas Board of Veterinary Medical Examiners licenses veterinarians. The usual U.S. route is graduation from an AVMA-accredited veterinary program, NAVLE passage, the Texas State Board Exam, and application eligibility. Accepted equivalency routes exist for other veterinary graduates. Undergraduate animal science or biology is preparation, not permission to practice veterinary medicine.',['https://veterinary.texas.gov/licensing/types-of-licenses/dvm/']);
set('architecture','Texas architect registration.',['Professional architecture education in the standard route.','Complete AXP experience and the ARE exams.','Apply to the Texas Board of Architectural Examiners.'],'The standard initial-registration route combines an accepted professional architecture degree, supervised architectural experience, the Architect Registration Examination, and Board eligibility requirements. Some building design is legally exempt, but exemption does not authorize using the protected architect title. Architecture-related undergraduate study is not automatically a qualifying professional degree.',['https://tbae.texas.gov/archregbyexam/','https://www.tbae.texas.gov/wp-content/uploads/2022/09/ArchitectRules.pdf'],'scope_dependent');
set('construction-management','No Texas general contractor license.',['Bachelor’s degree is typical; experience routes exist.','Austin contractor registration for permitted projects.','Electrical, plumbing, and HVAC work use licensed trades.'],'Austin states that Texas does not require a state general contractor license. Before construction associated with building/trade permits, contractors register with Austin Development Services and are assigned to permits. Construction management does not authorize independently performing regulated trade work. Project permits and employer qualifications are separate from an individual construction-manager license.',['https://www.austintexas.gov/development-services/contractor-registration'],'no_general_license');
set('librarian','Library jobs differ from Texas school-library certification.',['Library/information science master’s is typical.','No general license for ordinary public/academic librarian work.','School librarian: Texas educator certificate route.'],'Texas school librarian certification requires a master’s degree, an approved educator preparation program, the required certification examination, and two years of creditable classroom teaching experience. That is a school-specific credential, not a blanket requirement for all public or university librarian jobs. Employer qualifications for non-school roles are separate.',['https://tea.texas.gov/educators/certification/additional-certifications/student-services-certificates','https://www.bls.gov/ooh/education-training-and-library/librarians.htm',inventory],'scope_dependent');
set('interpreting','Texas court interpreting has a licensed route.',['Advanced proficiency in two languages.','General interpreting has no blanket Texas license.','Court route: orientation, exams, application, and background review.'],'The Judicial Branch Certification Commission licenses court interpreters. The initial route includes approved orientation before applying, written and oral examinations, fingerprinting, and other eligibility requirements. General business translation does not require this court license. Sign-language and specialized medical work have different credentials and role requirements; a court license is not a universal interpreting qualification.',['https://www.txcourts.gov/jbcc/licensed-court-interpreters/initial-licensure/licensure-requirements-fees/','https://www.bls.gov/ooh/media-and-communication/interpreters-and-translators.htm',inventory],'scope_dependent');
set('exercise-physiology','No general Texas exercise physiologist license.',['Bachelor’s degree is typical.','Clinical exercise credentials can support employment.','Athletic training and physical therapy are separately licensed.'],'The ordinary exercise physiologist role is not a Texas licensed occupation. Clinical certifications and employer education/CPR requirements remain relevant. Texas licenses athletic trainers and physical therapists; exercise physiology study or certification does not grant either protected scope.',['https://www.tdlr.texas.gov/at/about.htm','https://ptot.texas.gov/apply-for-a-license/','https://www.bls.gov/ooh/healthcare/exercise-physiologists.htm',inventory],'no_general_license');
set('geoscience','PG license for public geoscience services.',['Qualifying geoscience degree/coursework.','Standard route: five years of qualifying experience and exams.','Some employee, research, and other work is exempt.'],'Texas Board of Professional Geoscientists licenses public geoscience services in geology, geophysics, and soil science unless an exemption applies. The standard education route is a four-year course of study with at least 30 semester hours of geoscience, including 20 upper-level hours; qualifying experience and examinations also apply. Geoscientist-in-Training is an earlier credential and not independent PG authority.',['https://tbpg.state.tx.us/p-g-licensing-faqs/','https://tbpg.state.tx.us/exam-information/','https://statutes.capitol.texas.gov/Docs/OC/pdf/OC.1002.pdf'],'scope_dependent');

set('electrician','Texas electrician license for non-exempt work.',['Start with an apprentice license and supervised work.','Journeyman: 8,000 supervised hours and exam.','Public electrical work runs through a licensed contractor.'],'TDLR licenses electrical apprentices and higher levels. The journeyman route requires 8,000 hours under a master electrician; exam eligibility can begin after 7,000 hours, but the license requires all 8,000. Master and contractor credentials are later, separate steps. High-school/approved accelerated training routes and statutory exemptions can alter applicable credit or scope; an occupation median is not an apprentice starting wage.',['https://www.tdlr.texas.gov/electricians/','https://www.tdlr.texas.gov/electricians/apply/individuals/journeyman-electrician.htm']);
set('plumbing','Texas plumbing registration or license.',['Register as a plumber’s apprentice for the standard route.','Journeyman: 8,000 hours, approved instruction, and exam.','Work under the responsible master plumber’s business.'],'The Texas State Board of Plumbing Examiners standard journeyman examination route requires current apprentice/tradesman registration or qualifying out-of-state licensure, 8,000 trade hours, and a 48-hour approved course or qualifying apprenticeship program. Approved high-school/college and other statutory routes can provide alternatives. Pipefitting/steamfitting duties in the combined wage occupation can differ from regulated plumbing duties.',['https://tsbpe.texas.gov/license-types/journeyman/','https://statutes.capitol.texas.gov/Docs/OC/htm/OC.1301.htm']);
set('hvac','Texas ACR technician registration; contractor license is separate.',['Registered technician route starts at age 16.','Work through a licensed ACR contractor.','EPA Section 608 certification for covered refrigerant work.'],'TDLR distinguishes registered technician, certified technician, and contractor credentials. A registered technician under 18 needs direct supervision by a licensed contractor or certified technician. The ordinary contractor experience route uses 48 months in the previous 72 months, with an alternative for certified technicians and education/experience credits; it also requires an exam and insurance for public contracting. EPA refrigerant certification is federal and does not substitute for the Texas credential.',['https://www.tdlr.texas.gov/acr/','https://www.tdlr.texas.gov/news/2023/08/31/change-in-minimum-age-for-acr-registered-technicians/','https://web1.tdlr.texas.gov/media/pdf/ACR%20at%20a%20Glance.pdf','https://www.epa.gov/section608/section-608-technician-certification-requirements']);
set('carpentry','No Texas carpenter occupational license.',['Apprenticeship or on-the-job training.','Develop construction, measurement, and safety skills.','Austin contractor registration applies to permitted projects.'],'Texas does not require a general carpenter or general contractor license. Austin requires contractor registration before construction associated with building/trade permits. This does not authorize electrical, plumbing, HVAC, or other separately licensed work. Apprenticeship and employer safety qualifications are distinct from a state carpenter license.',['https://www.austintexas.gov/development-services/contractor-registration','https://www.bls.gov/ooh/construction-and-extraction/carpenters.htm'],'no_general_license');
set('automotive','No general Texas auto mechanic license.',['Technical training or supervised employer training.','ASE credentials are voluntary professional certifications.','Refrigerant and inspection duties have separate rules.'],'Ordinary vehicle repair has no blanket Texas mechanic occupational license. EPA Section 609 certification applies to servicing covered motor-vehicle air conditioning; it differs from building HVAC Section 608. Official vehicle inspection work has separate station/inspector authorization. Austin-area emissions testing is a different regulated activity from ordinary repair.',['https://gov.texas.gov/business/page/business-permits-office','https://www.epa.gov/mvac/section-609-technician-training-and-certification-programs','https://www.dps.texas.gov/section/vehicle-inspection'],'no_general_license');
set('emt','Texas DSHS EMT certification.',['At least 18 with a high school diploma or GED.','Complete an approved EMT course and National Registry requirements.','Apply to DSHS and complete fingerprinting.'],'DSHS certifies the EMT level after approved education, National Registry certification/examination, age and education qualifications, and state eligibility review. EMT certification is different from advanced EMT or paramedic preparation. Driving ambulance/emergency vehicles adds employer and driving qualifications; the EMT credential alone does not guarantee a driving assignment.',['https://www.dshs.texas.gov/dshs-ems-trauma-systems/ems-personnel-certification-licensure/initial-certification-licensure']);
set('chef','Food safety training; no general Texas chef license.',['Kitchen experience; culinary school is optional.','Accredited food handler training generally within 30 days.','Covered manager roles need food protection certification.'],'Texas food handler requirements apply to covered food employees, with rule-based exemptions. Food manager certification and restaurant permits are distinct from a general individual chef license. Austin food businesses operate under Austin Public Health permitting and food-safety rules. Chef/head cook is generally an experienced role, not the same wage category as a first line-cook job.',['https://www.dshs.texas.gov/licensing-food-handler-training-programs/frequently-asked-questions-food-handler-education-or-training-programs','https://www.austintexas.gov/department/food-enterprise-permits'],'scope_dependent');
set('dental-assisting','Texas radiology certificate for dental X-rays.',['Employer training or a dental assisting program.','X-ray route: diploma/GED, hands-on BLS, and approved exam/training.','Fingerprinting and Board application.'],'Ordinary chairside assisting and X-ray duties are different. To position or expose dental X-rays, a dental assistant needs the Texas State Board of Dental Examiners’ Dental Assistant Radiology Certificate. The route includes high-school completion/GED, current hands-on BLS, approved training/examination or qualifying DANB certification plus jurisprudence, and application eligibility. Expanded functions have their own duties/training rules; this is not a dental hygiene license.',['https://tsbde.texas.gov/licensing/dental-assistants/registered-dental-assistant-x-ray-certification/'],'scope_dependent');

// Additional reviewed mental-health roles. Employer examples remain distinct from licensure.
Object.assign(texasRequirements, {
 'psychiatric-aide':{summary:'Start with supervised patient care.',typicalEntry:'High school/GED + employer training',bullets:['Learn patient safety, communication, and daily-care support.','Austin State Hospital example: age 18+ and six months of work experience.','That employer requires CPR within 60 days and pre-employment screening.'],detail:'A degree is not the usual starting requirement. Texas’s state psychiatric nursing assistant classification generally prefers high school/GED and allows education/experience substitutions. Austin’s PNA I example requires six months of work experience; direct-care experience is preferred. Its training and screening requirements are employer requirements, not a universal occupational license.',sourceURLs:['https://www.bls.gov/ooh/healthcare/psychiatric-technicians-and-aides.htm','https://hr.sao.texas.gov/Compensation/JobDescriptions/2552.pdf','https://careers.hhs.texas.gov/hhscjobs/job/austin-psychiatric-nursing-assistant-i-tx-73301/1390652700'],reviewedAt:reviewed},
 'psychiatric-technician':{summary:'Build skills for supervised mental-health care.',typicalEntry:'Certificate is typical; associate degree adds preparation',bullets:['Study mental health, basic patient care, and safe documentation.','Complete supervised workplace or clinical training.','Texas option: Tarrant County College’s 60-credit Mental Health and Human Services AAS.'],detail:'Technicians commonly enter with a postsecondary certificate; some employers prefer additional college education. Tarrant County College explicitly prepares students for mental-health technician work, including practical placements. Its separate substance-abuse counseling license route is not a psychiatric-technician requirement.',sourceURLs:['https://www.bls.gov/ooh/healthcare/psychiatric-technicians-and-aides.htm','https://www.tccd.edu/academics/courses-and-programs/programs-a-z/credit/mental-health-and-human-services/','https://www.onetonline.org/link/localtraining/29-2053.00?st=TX'],reviewedAt:reviewed},
 'clinical-psychologist':{summary:'Doctoral training + Texas psychologist license.',typicalEntry:'Psychology doctorate, supervised experience, and licensing exams',bullets:['Earn a qualifying psychology doctorate with a formal internship.','Complete 3,500 supervised hours under Texas rules.','Pass the EPPP and Texas jurisprudence exam.'],detail:'The standard Texas Licensed Psychologist route includes 1,750 formal doctoral-internship hours and 1,750 additional supervised hours. Approved doctoral practicum or excess internship hours can satisfy part of the latter requirement. The application includes fingerprints and an NPDB self-query. School psychologist and psychological associate licenses have different requirements.',sourceURLs:['https://bhec.texas.gov/texas-state-board-of-examiners-of-psychologists/applying-for-a-psychology-license/how-to-become-a-licensed-psychologist/','https://bhec.texas.gov/wp-content/uploads/2026/06/PSY-Rulebook-2026-March.pdf'],reviewedAt:reviewed}
});

// Preserve specific employer expectations while removing generic location reminders.
Object.assign(texasRequirements,professionalRequirements,commonRequirements);
for(const record of Object.values(texasRequirements)){
 record.sourceURLs=[...new Set(record.sourceURLs.filter(Boolean))];
 record.training=record.bullets.slice(1).join(' ');
}
export const TEXAS_REQUIREMENTS_REVIEWED_AT=reviewed;
